func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
		return m, nil
	}
	if msg.Err != nil {
		alias := msg.EntryKey
		if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
			alias = entryAlias(*e)
		}
